function planIndex(date=selectedPlanDate){const d=new Date(date);d.setHours(0,0,0,0);return Math.max(0,Math.min(364,Math.round((d-PLAN_START)/DAY_MS)))}
function dateFromIndex(index){const d=new Date(PLAN_START);d.setDate(d.getDate()+Math.max(0,Math.min(364,index)));return d}
function setPlanDate(value){const d=value instanceof Date?new Date(value):new Date(`${value}T00:00:00`);if(Number.isNaN(d.getTime()))return;selectedPlanDate=d<PLAN_START?new Date(PLAN_START):d>PLAN_END?new Date(PLAN_END):d;render365();renderEnglish();renderMath();renderPolitics();renderFitness();renderNutrition()}
function phaseFor(i){if(i<=101)return{name:'阶段一 · 建立底盘',desc:'英语阅读与词汇每日不断线；数学以高数基础为核心；政治只做概念启蒙，不挤占数学英语。',start:0,end:101};if(i<=222)return{name:'阶段二 · 完成基础',desc:'数学完成高数、线代、概率基础框架并开始回收；英语提高精读强度；政治形成基础知识树。',start:102,end:222};if(i<=313)return{name:'阶段三 · 系统强化',desc:'数学进入综合题和章节训练；英语强化题型意识；政治由概念阅读转入课程与选择题理解。',start:223,end:313};return{name:'阶段四 · 暑期提升',desc:'以章节限时、错题二刷和讲义框架复述为主，为下一阶段正式考研复习建立高起点。',start:314,end:364}}
