function getDailyPlan(i){return{index:i,date:dateFromIndex(i),phase:phaseFor(i),english:englishFor(i),math:mathFor(i),politics:politicsFor(i)}}

function getCurrentWeek(){
 if(!settings.termStart) return null;
 const start=new Date(`${settings.termStart}T00:00:00`), now=new Date(); now.setHours(0,0,0,0);
 return Math.floor((now-start)/604800000)+1;
}
function parseWeeks(text){
 const cleaned=String(text||'').replace(/[，、\s]/g,',').replace(/第|周|单|双/g,''); const set=new Set();
 cleaned.split(',').filter(Boolean).forEach(part=>{const m=part.match(/^(\d+)\s*[-—~至]\s*(\d+)$/);if(m){let a=+m[1],b=+m[2];for(let i=Math.min(a,b);i<=Math.max(a,b);i++)set.add(i)}else if(/^\d+$/.test(part))set.add(+part)}); return [...set].sort((a,b)=>a-b);
}
function isActive(course,week){return parseWeeks(course.weeks).includes(+week)}
function coursesFor(day,week){return courses.filter(c=>+c.day===+day&&isActive(c,week)).sort((a,b)=>a.start-b.start)}
function navigate(id){document.querySelectorAll('.nav button,.view').forEach(x=>x.classList.remove('active'));document.querySelector(`.nav button[data-view="${id}"]`)?.classList.add('active');$(id).classList.add('active');if(id==='schedule')renderSchedule();if(id==='english')renderEnglish();if(id==='plan365')render365();if(id==='math')renderMath();if(id==='politics')renderPolitics();if(id==='fitness')renderFitness();if(id==='nutrition')renderNutrition();window.scrollTo({top:document.querySelector('.nav').offsetTop-8,behavior:'smooth'})}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));

function renderHeader(){
 const now=new Date(), cw=getCurrentWeek(); $('todayDate').textContent=`${now.getFullYear()}年${now.getMonth()+1}月${now.getDate()}日 · ${DAYS[now.getDay()]}`;
 $('currentWeek').textContent=cw&&cw>0&&cw<=settings.termWeeks?`${settings.termName||'本学期'} · 第${cw}周`:'未设置学期';
 const current=cw||viewWeekNumber; $('courseCount').textContent=courses.filter(c=>isActive(c,current)).length;
 $('wordDue').textContent=deck.filter(w=>w.status!=='new'&&w.due<=dateKey()).length;
}
function buildTodayTasks(){
 const now=new Date(), day=now.getDay(), week=getCurrentWeek()||viewWeekNumber, active=coursesFor(day,week), water=active.filter(c=>c.type==='water');
 const plan=getDailyPlan(planIndex(now)); const tasks=[];
 if(water.length) tasks.push({title:'利用可自习课程',detail:`${water.map(c=>c.name).join('、')}：背词或长难句 30–45 分钟`,tag:'英语'});
 const classLoad=active.reduce((n,c)=>n+(+c.end-+c.start+1),0);
 if(classLoad<=4) tasks.push({title:`数学 · ${plan.math.topic}`,detail:'课程/讲义 + 例题 + 练习，完成一个90–120分钟深度块',tag:'数学'}); else tasks.push({title:`数学保底 · ${plan.math.topic}`,detail:'只完成课程和基础例题，45–60分钟',tag:'数学'});
 tasks.push({title:`英语 · ${plan.english.title}`,detail:`阅读一篇 + 长难句 + 到期词 ${deck.filter(w=>w.status!=='new'&&w.due<=dateKey()).length} 个`,tag:'英语'});
 tasks.push({title:`政治 · ${plan.politics.title}`,detail:classLoad>6?'阅读概念卡并回答问题，15分钟':'阅读概念卡 + 课程/笔记，20–30分钟',tag:'政治'});
 if(active.length) tasks.push({title:'课程收口',detail:'核心内容、作业和疑问用 20 分钟归档',tag:'课程'});
 const fitness=fitnessInfoFor(now);if(fitness.type==='workout')tasks.push({title:fitness.muscle.title,detail:'按五日循环执行；可逐项打卡或顺延',tag:'训练'});else if(fitness.type==='rest')tasks.push({title:'训练恢复日',detail:'临时/固定休息，五日循环自动顺延',tag:'训练'});
 const energy=calculateEnergy();tasks.push({title:'饮食与恢复',detail:`今日热量目标约 ${energy.target} kcal，蛋白 130–150g，睡眠 7h+`,tag:'饮食'}); return tasks;
}
function renderToday(){
 const tasks=buildTodayTasks(), today=dateKey(), done=checks[today]||[]; $('todayTitle').textContent=`${DAYS[new Date().getDay()]}的最小闭环`;
 const cw=getCurrentWeek(); $('todayHint').textContent=cw?`系统正按第 ${cw} 周课表安排今天。课少时推进，课多时守住底线。`:'课程表尚未确定。先使用默认学习节奏，开学后设置学期并导入 PDF 即可自动适配。';
 $('todayTasks').innerHTML=tasks.map((t,i)=>`<div class="task ${done.includes(i)?'done':''}" data-index="${i}"><button class="task-check" aria-label="切换完成状态"></button><div class="task-copy"><b>${escapeHtml(t.title)}</b><span>${escapeHtml(t.detail)}</span></div><span class="tiny-tag">${t.tag}</span></div>`).join('');
 document.querySelectorAll('.task').forEach(el=>el.querySelector('.task-check').onclick=()=>{const i=+el.dataset.index,a=checks[today]||[];checks[today]=a.includes(i)?a.filter(x=>x!==i):[...a,i];write('tri-checks',checks);renderToday()});
 const pct=Math.round(done.length/tasks.length*100);$('percent').textContent=`${pct}%`;$('ring').style.setProperty('--p',`${pct}%`);$('streak').textContent=calcStreak();renderTodayCourses();
}
function calcStreak(){let n=0,d=new Date();for(let i=0;i<90;i++){if((checks[dateKey(d)]||[]).length)n++;else if(i>0)break;d.setDate(d.getDate()-1)}return n}
function renderTodayCourses(){
 const cw=getCurrentWeek()||viewWeekNumber, list=coursesFor(new Date().getDay(),cw);$('todayCourseMeta').textContent=courses.length?`第 ${cw} 周 · ${list.length} 门`:'尚未设置';
 $('todayCourses').innerHTML=list.length?list.map(c=>`<div class="compact-course ${c.type}"><b>${escapeHtml(c.name)}</b><span>第 ${c.start}–${c.end} 节 · ${escapeHtml(c.place||'地点未填')} · ${escapeHtml(c.weeks)}周</span></div>`).join(''):`<div class="empty">今天没有已录入课程。<br>可前往“动态课表”添加或导入。</div>`;
}
