function calculateEnergy(){const p=nutritionProfile,rmr=10*p.weight+6.25*p.height-5*p.age+(p.sex==='male'?5:-161),tdee=rmr*p.activity,target=Math.max(1200,tdee-p.deficit);return{rmr:Math.round(rmr),tdee:Math.round(tdee),target:Math.round(target)}}
function foodEstimate(food,grams){const ratio=grams/100,cal=Math.round(food.kcal*ratio),variance=food.v||.15;return{cal,low:Math.max(0,Math.round(cal*(1-variance))),high:Math.round(cal*(1+variance)),p:+(food.p*ratio).toFixed(1),c:+(food.c*ratio).toFixed(1),f:+(food.f*ratio).toFixed(1)}}
function foodMatches(query){const q=query.trim().toLowerCase();if(!q)return FOOD_DATA.filter((_,i)=>i<12);return FOOD_DATA.map((food,i)=>({food,i,text:`${food.name} ${food.aliases} ${food.cat}`.toLowerCase()})).filter(x=>x.text.includes(q)).sort((a,b)=>(a.food.name===q?-5:0)-(b.food.name===q?-5:0)||a.food.name.length-b.food.name.length).slice(0,12).map(x=>x.food)}
function renderFoodSuggestions(query=$('foodSearch').value){const list=foodMatches(query);$('foodSuggestions').innerHTML=list.length?list.map(food=>`<button data-food-choice="${FOOD_DATA.indexOf(food)}">${escapeHtml(food.name)} <small>${food.kcal} kcal/100g</small></button>`).join(''):'<span class="muted">没有匹配菜品，可使用下方手动填写。</span>';document.querySelectorAll('[data-food-choice]').forEach(b=>b.onclick=()=>selectFood(FOOD_DATA[+b.dataset.foodChoice]))}
